from bio import bio
bio("abu-ubayda", [
 ("هُوَ أَبُو عُبَيْدَةَ عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الْجَرَّاحِ، مِنْ قُرَيْشٍ.", "Er ist Abu ʿUbayda ʿAmir ibn ʿAbdillah ibn al-Dscharrah, aus Quraisch.", 1431),
 ("كَانَ مِنَ السَّابِقِينَ الْأَوَّلِينَ إِلَى الْإِسْلَامِ.", "Er gehörte zu den Ersten, die den Islam annahmen.", 1431),
 ("وَأَرَادَ أَبُو بَكْرٍ يَوْمَ السَّقِيفَةِ أَنْ يُوَلِّيَهُ الْخِلَافَةَ.", "Am Tag der Saqifa wollte Abu Bakr ihn zum Kalifen machen.", 1431),
 ("شَهِدَ لَهُ النَّبِيُّ ﷺ بِالْجَنَّةِ، وَسَمَّاهُ أَمِينَ الْأُمَّةِ.", "Der Prophet ﷺ bezeugte ihm das Paradies und nannte ihn den Vertrauenswürdigen der Umma.", 1432),
 ("قَالَ النَّبِيُّ ﷺ: إِنِّي أَبْعَثُ إِلَيْكُمْ رَجُلًا أَمِينًا، فَبَعَثَ أَبَا عُبَيْدَةَ.", "Der Prophet ﷺ sagte: Ich schicke euch einen vertrauenswürdigen Mann – und er schickte Abu ʿUbayda.", 1437),
 ("سُئِلَتْ عَائِشَةُ عَنْ أَحَبِّ الصَّحَابَةِ إِلَى النَّبِيِّ ﷺ، فَقَالَتْ: أَبُو بَكْرٍ، ثُمَّ عُمَرُ، ثُمَّ أَبُو عُبَيْدَةَ.", "ʿAischa wurde gefragt, welcher Gefährte dem Propheten ﷺ am liebsten war. Sie sagte: Abu Bakr, dann ʿUmar, dann Abu ʿUbayda.", 1436),
 ("تُوُفِّيَ سَنَةَ ثَمَانِ عَشْرَةَ فِي طَاعُونِ عَمَوَاسَ، وَلَهُ ثَمَانٌ وَخَمْسُونَ سَنَةً.", "Er starb im Jahr 18 an der Pest von ʿAmwas, mit 58 Jahren.", 1449),
], [
 ("hadith", "لِكُلِّ أُمَّةٍ أَمِيْنٌ، وَأَمِيْنُ هَذِهِ الأُمَّةِ: أَبُو عُبَيْدَةَ بنُ الجَرَّاحِ", "Jede Gemeinschaft hat einen Vertrauenswürdigen, und der Vertrauenswürdige dieser Umma ist Abu ʿUbayda ibn al-Dscharrah.", 1437, "اتفقا عليه – al-Bukhari und Muslim (laut adh-Dhahabi)"),
 ("athar", "شَهِدَ لَهُ النَّبِيُّ -ﷺ- بِالجَنَّةِ، وَسَمَّاهُ: أَمِيْنَ الأُمَّةِ، وَمَنَاقِبُهُ شَهِيْرَةٌ جَمَّةٌ.", "Der Prophet ﷺ bezeugte ihm das Paradies und nannte ihn den Vertrauenswürdigen der Umma; seine Vorzüge sind bekannt und zahlreich. (adh-Dhahabi)", 1432),
])
bio("talha", [
 ("هُوَ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ، مِنْ قُرَيْشٍ، أَبُو مُحَمَّدٍ.", "Er ist Talha ibn ʿUbaydillah, aus Quraisch, Abu Muhammad.", 1449),
 ("هُوَ أَحَدُ الْعَشَرَةِ الْمَشْهُودِ لَهُمْ بِالْجَنَّةِ.", "Er ist einer der Zehn, denen das Paradies bezeugt wurde.", 1450),
 ("سَبَقَ إِلَى الْإِسْلَامِ، وَأُوذِيَ فِي اللَّهِ، ثُمَّ هَاجَرَ.", "Er nahm früh den Islam an, wurde um Allahs willen verfolgt und wanderte dann aus.", 1451),
 ("غَابَ عَنْ بَدْرٍ فِي تِجَارَةٍ بِالشَّامِ، فَأَعْطَاهُ النَّبِيُّ ﷺ سَهْمَهُ وَأَجْرَهُ.", "Er war bei Badr wegen eines Handels in Syrien abwesend, doch der Prophet ﷺ gab ihm seinen Anteil und seinen Lohn.", 1451),
 ("وَيَوْمَ أُحُدٍ وَقَى النَّبِيَّ ﷺ بِيَدِهِ حَتَّى شَلَّتْ.", "Am Tag von Uhud schützte er den Propheten ﷺ mit seiner Hand, bis sie gelähmt war.", 1452),
 ("وَقَاتَلَ دُونَ النَّبِيِّ ﷺ حَتَّى قُطِعَتْ أَصَابِعُهُ.", "Er kämpfte zur Verteidigung des Propheten ﷺ, bis seine Finger abgetrennt wurden.", 1453),
 ("وَقَالَ النَّبِيُّ ﷺ يَوْمَ أُحُدٍ: أَوْجَبَ طَلْحَةُ.", "Der Prophet ﷺ sagte am Tag von Uhud: Talha hat (sich das Paradies) verdient.", 1452),
], [
 ("athar", "رَأَيْتُ يَدَ طَلْحَةَ الَّتِي وَقَى بِهَا النَّبِيَّ -ﷺ- يَوْمَ أُحُدٍ شَلاَّءَ.", "Ich sah die Hand Talhas, mit der er den Propheten ﷺ am Tag von Uhud schützte – sie war gelähmt. (Qays)", 1452, "أخرجه البخاري (laut adh-Dhahabi)"),
 ("hadith", "أَوجب طَلْحَةُ", "Talha hat es (sich) verdient.", 1452, "بإسناد حسن (laut adh-Dhahabi, Tirmidhi)"),
])
bio("zubayr", [
 ("هُوَ الزُّبَيْرُ بْنُ الْعَوَّامِ، وَأُمُّهُ صَفِيَّةُ عَمَّةُ النَّبِيِّ ﷺ.", "Er ist az-Zubayr ibn al-ʿAwwam; seine Mutter Safiyya war die Tante des Propheten ﷺ.", 1467),
 ("هُوَ حَوَارِيُّ رَسُولِ اللَّهِ ﷺ، وَأَحَدُ الْعَشَرَةِ الْمَشْهُودِ لَهُمْ بِالْجَنَّةِ.", "Er ist der Jünger (Hawari) des Gesandten Allahs ﷺ und einer der Zehn, denen das Paradies bezeugt wurde.", 1467),
 ("وَهُوَ أَحَدُ السِّتَّةِ أَهْلِ الشُّورَى.", "Er gehörte zu den sechs Männern des Beratungsrates (Schura).", 1467),
 ("وَكَانَ أَوَّلَ مَنْ سَلَّ سَيْفَهُ فِي سَبِيلِ اللَّهِ.", "Er war der Erste, der auf Allahs Weg sein Schwert zog.", 1467),
 ("أَسْلَمَ وَهُوَ شَابٌّ صَغِيرٌ.", "Er nahm den Islam als junger Mann an.", 1467),
 ("وَكَانَ قَلِيلَ الرِّوَايَةِ، لِأَنَّهُ سَمِعَ النَّبِيَّ ﷺ يُحَذِّرُ مِنَ الْكَذِبِ عَلَيْهِ.", "Er überlieferte wenig, weil er gehört hatte, wie der Prophet ﷺ davor warnte, ihm etwas Falsches zuzuschreiben.", 1470),
], [
 ("athar", "حَوَارِيُّ رَسُوْلِ اللهِ -ﷺ- وَابْنُ عَمَّتِهِ صَفِيَّةَ بِنْتِ عَبْدِ المُطَّلِبِ، وَأَحَدُ العَشرَةِ المَشْهُوْدِ لَهُم بِالجَنَّةِ", "Der Jünger des Gesandten Allahs ﷺ, Sohn seiner Tante Safiyya bint ʿAbd al-Muttalib, einer der Zehn, denen das Paradies bezeugt wurde. (adh-Dhahabi)", 1467),
 ("athar", "أَمَا إِنِّي لَمْ أُفَارِقْهُ مُنْذُ أَسْلَمْتُ، وَلَكِنْ سَمِعْتُهُ يَقُوْلُ: (مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَليَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ)", "Ich habe mich nie von ihm getrennt, seit ich Muslim wurde; aber ich hörte ihn sagen: Wer absichtlich über mich lügt, der nehme seinen Platz im Feuer ein. (az-Zubayr)", 1470, "أخرجه البخاري (laut adh-Dhahabi)"),
])
bio("abdurrahman-ibn-awf", [
 ("هُوَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ، مِنْ بَنِي زُهْرَةَ، أَبُو مُحَمَّدٍ.", "Er ist ʿAbd ar-Rahman ibn ʿAwf, aus dem Stamm Zuhra, Abu Muhammad.", 1494),
 ("هُوَ أَحَدُ الْعَشَرَةِ، وَأَحَدُ أَهْلِ الشُّورَى، وَشَهِدَ بَدْرًا.", "Er ist einer der Zehn, einer der Männer der Schura, und er nahm an Badr teil.", 1494),
 ("وَكَانَ أَحَدَ الثَّمَانِيَةِ الَّذِينَ بَادَرُوا إِلَى الْإِسْلَامِ.", "Er war einer der acht, die als Erste zum Islam eilten.", 1494),
 ("كَانَ اسْمُهُ فِي الْجَاهِلِيَّةِ عَبْدَ عَمْرٍو، فَسَمَّاهُ النَّبِيُّ ﷺ عَبْدَ الرَّحْمَنِ.", "In der vorislamischen Zeit hieß er ʿAbd ʿAmr; der Prophet ﷺ nannte ihn ʿAbd ar-Rahman.", 1495),
 ("شَهِدَ عِنْدَ عُمَرَ أَنَّ النَّبِيَّ ﷺ أَخَذَ الْجِزْيَةَ مِنْ مَجُوسِ هَجَرَ.", "Er bezeugte vor ʿUmar, dass der Prophet ﷺ von den Zoroastriern von Hadschar die Dschizya genommen hatte.", 1496),
 ("وَكَانَ مُوَفَّقًا فِي التِّجَارَةِ، وَتَرَكَ مَالًا كَثِيرًا.", "Er war im Handel erfolgreich und hinterließ großen Besitz.", 1518),
 ("وَقَالَ الذَّهَبِيُّ عَنْهُ: هَذَا هُوَ الْغَنِيُّ الشَّاكِرُ.", "adh-Dhahabi sagte über ihn: Das ist der dankbare Reiche.", 1518),
 ("تُوُفِّيَ سَنَةَ اثْنَتَيْنِ وَثَلَاثِينَ، وَدُفِنَ بِالْبَقِيعِ.", "Er starb im Jahr 32 und wurde im Baqiʿ begraben.", 1518),
], [
 ("athar", "وَهُوَ أَحَدُ الثَّمَانِيَةِ الَّذِيْنَ بَادَرُوا إِلَى الإِسْلاَمِ.", "Er ist einer der acht, die als Erste zum Islam eilten. (adh-Dhahabi)", 1494),
 ("athar", "قُلْتُ: هَذَا هُوَ الغَنِيُّ الشَاكِرُ", "Ich (adh-Dhahabi) sage: Das ist der dankbare Reiche.", 1518),
])
bio("sad", [
 ("هُوَ سَعْدُ بْنُ أَبِي وَقَّاصٍ، مِنْ بَنِي زُهْرَةَ، أَبُو إِسْحَاقَ.", "Er ist Saʿd ibn Abi Waqqas, aus dem Stamm Zuhra, Abu Ishaq.", 1519),
 ("هُوَ أَحَدُ الْعَشَرَةِ، وَمِنَ السَّابِقِينَ الْأَوَّلِينَ، وَشَهِدَ بَدْرًا وَالْحُدَيْبِيَةَ.", "Er ist einer der Zehn, einer der Ersten im Islam, und war bei Badr und Hudaybiya dabei.", 1519),
 ("وَهُوَ أَحَدُ السِّتَّةِ أَهْلِ الشُّورَى.", "Er gehörte zu den sechs Männern der Schura.", 1519),
 ("أَسْلَمَ وَعُمُرُهُ سَبْعَ عَشْرَةَ سَنَةً.", "Er nahm den Islam mit 17 Jahren an.", 1522),
 ("قَالَ سَعْدٌ: إِنِّي لَأَوَّلُ الْمُسْلِمِينَ رَمَى الْمُشْرِكِينَ بِسَهْمٍ.", "Saʿd sagte: Ich war der erste Muslim, der einen Pfeil auf die Götzendiener schoss.", 1524),
 ("وَقَالَ لَهُ النَّبِيُّ ﷺ: ارْمِ، فِدَاكَ أَبِي وَأُمِّي.", "Der Prophet ﷺ sagte zu ihm: Schieß – mein Vater und meine Mutter seien dir Lösegeld!", 1524),
 ("وَلَمَّا شَكَاهُ قَوْمٌ إِلَى عُمَرَ، قَالَ إِنَّهُ يُصَلِّي كَمَا صَلَّى النَّبِيُّ ﷺ.", "Als sich Leute bei ʿUmar über ihn beschwerten, sagte er, er bete so, wie der Prophet ﷺ gebetet hat.", 1520),
 ("تُوُفِّيَ فِي قَصْرِهِ بِالْعَقِيقِ، وَحُمِلَ إِلَى الْمَدِينَةِ.", "Er starb in seinem Haus in al-ʿAqiq und wurde nach Medina getragen.", 1523),
], [
 ("athar", "مَا جَمَعَ رَسُوْلُ اللهِ -ﷺ- أَبَوَيْهِ لأَحَدٍ قَبْلِي", "Vor mir hat der Gesandte Allahs ﷺ für niemanden seine beiden Eltern (als Lösegeld) genannt. (Saʿd)", 1524, "متفق عليه (laut adh-Dhahabi)"),
 ("athar", "وَإِنِّي لأَوَّلُ المُسْلِمِيْنَ رَمَى المُشْرِكِيْنَ بِسَهْمٍ", "Ich war der erste Muslim, der einen Pfeil auf die Götzendiener schoss. (Saʿd)", 1524, "متفق عليه (laut adh-Dhahabi)"),
])
bio("said-ibn-zayd", [
 ("هُوَ سَعِيدُ بْنُ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ، مِنْ بَنِي عَدِيٍّ، أَبُو الْأَعْوَرِ.", "Er ist Saʿid ibn Zayd ibn ʿAmr ibn Nufayl, aus dem Stamm ʿAdi, Abu l-Aʿwar.", 1550),
 ("هُوَ أَحَدُ الْعَشَرَةِ الْمَشْهُودِ لَهُمْ بِالْجَنَّةِ، وَمِنَ السَّابِقِينَ الْأَوَّلِينَ.", "Er ist einer der Zehn, denen das Paradies bezeugt wurde, und einer der Ersten im Islam.", 1550),
 ("وَشَهِدَ الْمَشَاهِدَ مَعَ النَّبِيِّ ﷺ.", "Er nahm an den Feldzügen mit dem Propheten ﷺ teil.", 1550),
 ("وَشَهِدَ فَتْحَ دِمَشْقَ، فَوَلَّاهُ أَبُو عُبَيْدَةَ عَلَيْهَا.", "Er war bei der Eroberung von Damaskus dabei, und Abu ʿUbayda setzte ihn dort als Statthalter ein.", 1551),
 ("وَكَانَ أَبُوهُ زَيْدٌ قَدْ تَرَكَ عِبَادَةَ الْأَصْنَامِ قَبْلَ الْإِسْلَامِ، وَطَلَبَ الدِّينَ الْحَقَّ.", "Sein Vater Zayd hatte schon vor dem Islam die Götzenanbetung verlassen und nach der wahren Religion gesucht.", 1552),
 ("وَرَوَى عَنِ النَّبِيِّ ﷺ: مَنْ ظَلَمَ مِنَ الْأَرْضِ شِبْرًا طُوِّقَهُ مِنْ سَبْعِ أَرَضِينَ.", "Er überlieferte vom Propheten ﷺ: Wer eine Spanne Land zu Unrecht nimmt, dem wird es von sieben Erden um den Hals gelegt.", 1552),
], [
 ("athar", "أَحَدُ العَشَرَةِ المَشْهُوْدِ لَهُم بِالجَنَّةِ، وَمِنَ السَّابِقِيْنَ الأَوَّلِيْنَ البَدْرِيِّيْنَ", "Einer der Zehn, denen das Paradies bezeugt wurde, einer der ersten Muslime und der Badr-Kämpfer. (adh-Dhahabi)", 1550),
 ("hadith", "مَنْ ظَلَمَ مِنَ الأَرْضِ شِبرًا طُوِّقَهُ مِنْ سَبعِ أَرَضِيْنَ", "Wer eine Spanne Land zu Unrecht nimmt, dem wird es von sieben Erden um den Hals gelegt.", 1552, "أخرجه البخاري (laut adh-Dhahabi)"),
])
